import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../services/supabaseService';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { useToast } from '../../contexts/ToastContext';

const ProjectSquadsHub = () => {
    const navigate = useNavigate();
    const { addToast } = useToast();
    const { user } = useSelector((state) => state.auth);
    const [missions, setMissions] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeFilter, setActiveFilter] = useState('All');

    const filters = ['All', 'Tech Development', 'Social Impact', 'Research', 'Design Mastery', 'Business Strategy', 'Summer Camp Build'];

    useEffect(() => {
        const fetchAllMissions = async () => {
            try {
                const data = await supabaseService.getOpenMissions();
                setMissions(data || []);
            } catch (err) {
                console.error("Failed to fetch global missions:", err);
            } finally {
                setIsLoading(false);
            }
        };

        fetchAllMissions();
    }, []);

    const filteredMissions = activeFilter === 'All' 
        ? missions 
        : missions.filter(m => m.mission === activeFilter);

    return (
        <div className="min-h-screen bg-slate-950 flex flex-col">
            <Header />

            <main className="flex-1">
                {/* Hub Hero - Mission Control Aesthetic */}
                <section className="relative pt-32 pb-20 overflow-hidden border-b border-white/5">
                    <div className="absolute inset-0 z-0">
                        <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_20%_30%,rgba(16,185,129,0.1)_0%,transparent_50%)]" />
                        <div className="absolute top-1/2 right-0 w-96 h-96 bg-primary/5 rounded-full blur-[120px]" />
                        
                        {/* Grid Pattern Overlay */}
                        <div className="absolute inset-0 opacity-[0.03]" style={{ backgroundImage: 'radial-gradient(circle, #fff 1px, transparent 1px)', backgroundSize: '40px 40px' }} />
                    </div>

                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10 text-center">
                        <div className="flex justify-start mb-8">
                            <button 
                                onClick={() => navigate('/academy')}
                                className="flex items-center gap-2 text-slate-500 hover:text-white transition-colors group"
                            >
                                <Icon name="ArrowLeft" size={18} className="group-hover:-translate-x-1 transition-transform" />
                                <span className="text-sm font-bold uppercase tracking-widest">Back to Academy</span>
                            </button>
                        </div>
                        <div className="inline-flex items-center gap-3 px-4 py-2 bg-emerald-500/10 border border-emerald-500/20 rounded-full mb-8 backdrop-blur-md">
                            <Icon name="Rocket" size={18} className="text-emerald-400" />
                            <span className="text-xs font-black uppercase tracking-[0.3em] text-emerald-400">Institutional Venture Hub</span>
                        </div>
                        <h1 className="text-5xl md:text-8xl font-black text-white italic tracking-tighter leading-[0.85] mb-8">
                            GLOBAL MISSION <br />
                            <span className="text-emerald-400">CONTROL</span>
                        </h1>
                        <p className="text-xl text-slate-400 font-medium max-w-2xl mx-auto leading-relaxed mb-12">
                            Step into the arena where world-class scholars build the next generation of global solutions. Find a squad, launch a mission, and claim your legacy.
                        </p>
                        
                        <div className="flex flex-wrap justify-center gap-4">
                            <Button 
                                size="xl" 
                                className="bg-emerald-500 hover:bg-emerald-600 text-white font-black italic px-12 shadow-2xl shadow-emerald-500/20"
                                onClick={() => navigate('/student-dashboard', { state: { tab: 'project-squads' } })}
                                iconName="Plus"
                            >
                                START A MISSION
                            </Button>
                            <Button 
                                size="xl" 
                                variant="outline" 
                                className="border-white/10 text-white hover:bg-white/5 font-black italic px-12"
                            >
                                VIEW LEADERBOARD
                            </Button>
                        </div>
                    </div>
                </section>

                {/* Filters & Directory */}
                <section className="py-20">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 mb-16">
                            <div className="flex flex-wrap gap-2">
                                {filters.map(filter => (
                                    <button
                                        key={filter}
                                        onClick={() => setActiveFilter(filter)}
                                        className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                                            activeFilter === filter 
                                            ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20 scale-105' 
                                            : 'bg-white/5 text-slate-400 hover:bg-white/10 border border-white/5'
                                        }`}
                                    >
                                        {filter}
                                    </button>
                                ))}
                            </div>
                            <div className="flex items-center gap-3 px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-slate-400">
                                <Icon name="Search" size={16} />
                                <input 
                                    className="bg-transparent border-none outline-none text-sm font-medium w-48 focus:w-64 transition-all"
                                    placeholder="Search Missions..."
                                />
                            </div>
                        </div>

                        {/* Squads Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {isLoading ? (
                                [1, 2, 3, 4, 5, 6].map(i => (
                                    <div key={i} className="h-80 bg-white/5 rounded-[2.5rem] animate-pulse" />
                                ))
                            ) : filteredMissions.length > 0 ? (
                                filteredMissions.map(mission => (
                                    <div key={mission.id} className="group relative bg-white/[0.02] hover:bg-white/[0.06] border border-white/10 rounded-[2.5rem] p-10 transition-all duration-700 hover:-translate-y-2 flex flex-col">
                                        <div className="absolute top-0 right-0 p-8">
                                            <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center border border-emerald-500/20 group-hover:bg-emerald-500 transition-colors">
                                                <Icon name="ArrowUpRight" size={20} className="text-emerald-400 group-hover:text-white" />
                                            </div>
                                        </div>

                                        <div className="mb-10">
                                            <div className="px-3 py-1 bg-emerald-500/10 rounded-lg text-[9px] font-black uppercase tracking-widest text-emerald-400 border border-emerald-500/20 w-fit mb-6">
                                                {mission.mission}
                                            </div>
                                            <h3 className="text-3xl font-black text-white italic tracking-tighter mb-4 group-hover:text-emerald-400 transition-colors">
                                                {mission.name}
                                            </h3>
                                            <p className="text-slate-400 text-sm font-medium leading-relaxed line-clamp-3">
                                                {mission.description}
                                            </p>
                                        </div>

                                        <div className="mt-auto pt-8 border-t border-white/5 flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <div className="flex -space-x-2">
                                                    {[1, 2, 3].map(i => (
                                                        <img key={i} src={`https://i.pravatar.cc/100?u=${mission.id + i}`} className="w-8 h-8 rounded-full border-2 border-slate-950 shadow-2xl" />
                                                    ))}
                                                </div>
                                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">
                                                    {mission.members_count || 3} Slots Active
                                                </span>
                                            </div>
                                            <Button 
                                                size="sm" 
                                                variant="secondary" 
                                                className="font-black italic px-6 rounded-xl"
                                                onClick={() => {
                                                    if (!user) {
                                                        addToast('Please login to apply for a squad.', 'warning');
                                                        navigate('/login');
                                                    } else {
                                                        navigate('/student-dashboard', { state: { tab: 'project-squads' } });
                                                    }
                                                }}
                                            >
                                                APPLY
                                            </Button>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="col-span-full py-20 text-center bg-white/5 border border-dashed border-white/10 rounded-[3rem]">
                                    <Icon name="Rocket" size={48} className="text-slate-600 mx-auto mb-6" />
                                    <h3 className="text-xl font-bold text-white mb-2">No missions found in this sector.</h3>
                                    <p className="text-slate-500 mb-8">Be the first to launch a venture in this category.</p>
                                    <Button variant="secondary" onClick={() => navigate('/student-dashboard', { state: { tab: 'project-squads' } })}>Launch Mission</Button>
                                </div>
                            )}
                        </div>
                    </div>
                </section>
            </main>

            <Footer />
        </div>
    );
};

export default ProjectSquadsHub;
